import { z } from 'zod';

/**
 * Invoke options for LLM call
 */
export declare interface InvokeOptions {
    /**
     * Force LLM to call a specific tool by name.
     * If provided: tool_choice = { type: 'function', function: { name: toolChoiceName } }
     * If not provided: tool_choice = 'required' (must call some tool, but model chooses which)
     */
    toolChoiceName?: string;
    /**
     * Response normalization function.
     * Called before parsing the response.
     * Used to fix various response format errors from the model.
     */
    normalizeResponse?: (response: any) => any;
}

/**
 * Invoke result (strict typing, supports generics)
 */
export declare interface InvokeResult<TResult = unknown> {
    toolCall: {
        name: string;
        args: any;
    };
    toolResult: TResult;
    usage: {
        promptTokens: number;
        completionTokens: number;
        totalTokens: number;
        cachedTokens?: number;
        reasoningTokens?: number;
    };
    rawResponse?: unknown;
}

export declare class LLM extends EventTarget {
    config: Required<LLMConfig>;
    client: LLMClient;
    constructor(config: LLMConfig);
    /**
     * - call llm api *once*
     * - invoke tool call *once*
     * - return the result of the tool
     */
    invoke(messages: Message[], tools: Record<string, Tool>, abortSignal: AbortSignal, options?: InvokeOptions): Promise<InvokeResult>;
}

/**
 * LLM Client interface
 * Note: Does not use generics because each tool in the tools array has different types
 */
export declare interface LLMClient {
    invoke(messages: Message[], tools: Record<string, Tool>, abortSignal?: AbortSignal, options?: InvokeOptions): Promise<InvokeResult>;
}

/**
 * LLM configuration
 */
export declare interface LLMConfig {
    baseURL: string;
    apiKey: string;
    model: string;
    temperature?: number;
    maxRetries?: number;
    /**
     * Custom fetch function for LLM API requests.
     * Use this to customize headers, credentials, proxy, etc.
     * The response should follow OpenAI API format.
     */
    customFetch?: typeof globalThis.fetch;
}

/**
 * Message format - OpenAI standard (industry standard)
 */
export declare interface Message {
    role: 'system' | 'user' | 'assistant' | 'tool';
    content?: string | null;
    tool_calls?: {
        id: string;
        type: 'function';
        function: {
            name: string;
            arguments: string;
        };
    }[];
    tool_call_id?: string;
    name?: string;
}

export declare function parseLLMConfig(config: LLMConfig): Required<LLMConfig>;

/**
 * Tool definition - uses Zod schema (LLM-agnostic)
 * Supports generics for type-safe parameters and return values
 */
export declare interface Tool<TParams = any, TResult = any> {
    description?: string;
    inputSchema: z.ZodType<TParams>;
    execute: (args: TParams) => Promise<TResult>;
}

